        no_wait=true,
      )
      let child = @process.spawn(
        group,
        "ssh",
        ssh_args(
          state,
          lease=required(state, "socketDirectory") + "/primary-proxy.lock",
        ) +
        [
          "-M",
          "-S",
          control_socket(state, directory),
          state,
          [
            "--result-format",
            "json",
            "workspace",
            "up",
            required(state, "workspaceId"),
            "--ide-launch",
            "skip",
          ],
          "workspace-resume",
        ),
      )
      codex_addon(state)
      if required(state, "connection") == "orca-server" &&
        server_is_running(state) {
        emit_connection(state, false, existing=previous)
      } else {
        emit_connection(state, false)
      }
