///|
async fn invoke(
  mode : String,
  env : Map[String, String],
  directory : String,
  payload? : Json,
) -> (Int32, String, String) {
  let executable = integration_binary()
  let input = if payload is Some(value) {
    @fs.write_file(directory + "/stdin.json", value.stringify())
    Some(@process.redirect_from_file(directory + "/stdin.json"))
  } else {
    None
  }
  let (status, stdout, stderr) = @process.collect_output(
    executable,
    if (mode == "reconnect" || mode == "restart") && payload is Some(_) {
      [mode, "--receipt"]
    } else {
      [mode]
    },
    extra_env=env,
    stdin?=input,
  )
  let diagnostics = if status != 0 { fixture_process_errors(env) } else { "" }
  (status, stdout.text(), stderr.text() + diagnostics)
}

///|
async fn fixture_process_errors(env : Map[String, String]) -> String {
  let diagnostics = []
  try {
    let path = env.get("XDG_STATE_HOME").unwrap() +
      "/orca-env-devsy/events.jsonl"
    for line in @fs.read_file(path).text().split("\n") {
      if line == "" {
        continue
      }
      let event = @json.parse(line.to_owned())
      if field(event, "status") != Some(Json::string("process-error")) {
        continue
      }
      let safe = Json::empty_object()
      for name in ["process_os", "process_utf8", "process_api"] {
        if field(event, "errorType") == Some(Json::string(name)) {
          set_field(safe, "errorType", Json::string(name))
        }
      }
      for name in ["read"] {
        if field(event, "phase") == Some(Json::string(name)) {
          set_field(safe, "phase", Json::string(name))
        }
      }
///|
async fn save_diagnostic(
  stage : String,
  status : String,
  exit_code? : Int32,
  error_type? : String,
  phase? : String,
  duration_ms? : Double,
  attempt? : Int32,
  retry_delay_ms? : Int32,
  os_errno? : Int32,
  source? : CreateEvidence,
  error_message? : String,
  details_truncated~ : Bool = false,
  tunnel_directory? : String,
) -> Unit {
  if @env.get_env_var("ORCA_ENV_DEVSY_RECORDING") == Some("0") {
    return
  }
  try {
    let dir = adapter_state_home()
    @fs.mkdir(dir, permission=0o700, recursive=true, allow_exist=true)
    @fs.chmod(dir, 0o700)
    let path = dir + "/events.jsonl"
    if @fs.exists(path) &&
      @fs.kind(path, follow_symlink=false) != @fs.FileKind::Regular {
      return
    }
    if @fs.exists(path) && @fs.file_size(path) > 262144L {
      @fs.remove(path)
    }
    let event : Json = {
      "stage": stage,
      "status": status,
      "time": @env.now().to_string(),
      "runId": recording_run_id,
      "adapterVersion": version,
    }
    if create_recording.attempt > 0 {
      set_field(
        event,
        "createAttempt",
        Json::number(create_recording.attempt.to_double()),
      )
      set_field(event, "createPhase", Json::string(create_recording.phase))
    }
    if error_message is Some(message) {
      set_field(event, "errorMessage", Json::string(message))
      set_field(event, "detailsTruncated", Json::boolean(details_truncated))
    }
    if tunnel_directory is Some(directory) {
      set_field(event, "tunnelDirectory", Json::string(directory))
    }
    if source is Some(evidence) {
      set_field(event, "source", evidence.to_json())
    }
    if os_errno is Some(code) && code > 0 && code < 4096 {
      set_field(event, "osErrno", Json::number(code.to_double()))
    }
    if exit_code is Some(code) {
      set_field(event, "exitCode", Json::number(code.to_double()))
    }
    for pair in [("errorType", error_type), ("phase", phase)] {
      if pair.1 is Some(text) {
        set_field(event, pair.0, Json::string(text))
      }
    }
    if duration_ms is Some(value) {
      set_field(event, "durationMs", Json::number(value))
    }
    if attempt is Some(value) {
      set_field(event, "attempt", Json::number(value.to_double()))
    }
    if retry_delay_ms is Some(value) {
      set_field(event, "retryDelayMs", Json::number(value.to_double()))
    }
    @fs.write_file(
      path,
      event.stringify() + "\n",
      permission=0o600,
      append=true,
      create_mode=@fs.OpenOrCreate,
    )
  } catch {
    _ => ()
  }
}

///|
let recording_run_id : String = @env.now().to_string()

///|
fn process_error_type(output : String) -> String {
  let text = output.to_lower()
  if text.contains("out of memory") || text.contains("cannot allocate memory") {
    "memory_exhausted"
  } else if text.contains("no space left on device") {
    "disk_exhausted"
  } else if text.contains("address already in use") ||
    text.contains("addrinuse") {
    "address_in_use"
  } else if text.contains("permission denied (publickey") ||
    text.contains("authentication failed") {
    "authentication_failed"
  } else if text.contains("host key verification failed") {
    "host_key_failed"
  } else if text.contains("connection refused") {
    "connection_refused"
  } else if text.contains("connection timed out") ||
    text.contains("operation timed out") {
    "connection_timeout"
  } else if text.contains("could not resolve hostname") {
    "name_resolution"
  } else if text.contains("controlsocket") || text.contains("control socket") {
    "control_socket"
  } else if text.contains("build_vm:") {
    "vm_boot"
  } else if text.contains("create microsandbox vm") && text.contains("network:") {
    "vm_network"
  } else if text.contains("create microsandbox vm") && text.contains("mount:") {
    "vm_mount"
  } else if text.contains("ensure microsandbox final image") ||
    text.contains("prepare microsandbox final image") {
    "vm_image"
  } else if text.contains("create microsandbox vm") {
    "vm_create"
  } else if text.contains("start microsandbox vm") {
    "vm_start"
  } else if text.contains("no such file or directory") ||
    text.contains("not found") {
    "missing_resource"
  } else if text.contains("permission denied") {
    "permission_denied"
  } else if text.contains("database is locked") ||
    text.contains("database locked") {
    "database_locked"
  } else if text.contains("too many open files") {
    "file_limit"
  } else {
    "process_exit"

output.text:
{"chunk_id":"d80730","wall_time_seconds":0.000007292,"exit_code":0,"original_token_count":5314,"output":"      @process.collect_output(
        "ssh",
        ssh_args(state) + ["-S", control_socket(state, directory), "-O", "exit"],
      ),
    )
  }
  @fs.rmdir(directory) catch {
    _ => ()
  }
  progress_message("ssh-tunnel-close: done (" + progress_timing(started) + ")")
}

///|
pub async fn tunnel_worker(directory : String) -> Unit {
  let lock = @fs.open(
    directory + "/worker.lock",
    mode=ReadWrite,
    create_mode=OpenOrCreate,
    permission=0o600,
  )
  defer lock.close()
  if !lock.try_lock(Exclusive) {
    return
  }
  let state = @json.parse(@fs.read_file(directory + "/state.json").text())
  validate_state(state)
  let forwarding = match field(state, "localPort") {
    Some(Json::Number(value, ..)) =>
      ["-L", "127.0.0.1:\{value.to_int()}:127.0.0.1:47121"]
    None if field(state, "connection") == Some(Json::string("ssh")) => []
    _ => raise AdapterError("Missing tunnel port")
  }
  let enabled = directory + "/enabled"
  let mut adopted = try {
    check_tunnel(state, directory)
    true
  } catch {
    _ => false
  }
  let mut attempt = 0
  defer @async.protect_from_cancel(async fn() {
    stop_tunnel_master(state, directory)
  })
  while @fs.exists(enabled) {
    tunnel_status(directory, "connecting")
    git_relay_status(directory, "pending")
    let mut terminal = false
    @async.with_task_group(async fn(group) {
      group.spawn_bg(no_wait=true, async fn() {
        while @fs.exists(enabled) {
          @async.sleep(100)
        }
        raise AdapterError("Tunnel disabled")
      })
      guard worker_workspace(state, directory) is Some(current) &&
        field(current, "uid") == field(state, "workspaceUid") else {
        if @fs.exists(enabled) {
          @fs.remove(enabled)
        }
        terminal = true
        tunnel_status(directory, "ownership-error")
        return
      }
      if field(current, "running") != Some(Json::boolean(true)) {
        terminal = true
        tunnel_status(directory, "workspace-stopped")
        return
      }
      @fs.mkdir(
        required(state, "socketDirectory"),
        permission=0o700,
        allow_exist=true,
      )
      let sink = @process.redirect_to_file("/dev/null", shared=true)
      defer sink.close()
      let (errors, stderr) = @process.read_from_process()
      defer errors.close()
      let classified = group.spawn(
        async fn() { tunnel_errors(errors) },
        no_wait=true,
      )
      let child = if adopted {
        save_diagnostic("orca-tunnel", "adopted", tunnel_directory=directory)
        None
      } else {
        Some(
          @process.spawn(
            group,
            "ssh",
            ssh_args(
              state,
              lease=required(state, "socketDirectory") + "/primary-proxy.lock",
            ) +
            [
              "-M",
              "-S",
              control_socket(state, directory),
              "-N",
              "-o",
              "ExitOnForwardFailure=yes",
              "-o",
              "ServerAliveInterval=10",
              "-o",
              "ServerAliveCountMax=3",
            ] +
            forwarding,
            stdin=@process.redirect_from_file("/dev/null"),
            stdout=sink,
            stderr~,
            no_wait=true,
          ),
        )
      }
      adopted = false
      let git_enabled = @async.with_timeout(10000, async fn() {
        git_forwarding_enabled(state)
      })
      let mut next_probe = @env.now()
      let mut next_check = @env.now()
      let mut failures = 0
      let mut connected = false
      while @fs.exists(enabled) {
        if child is Some(child) && child.try_wait() is Some(code) {
          save_diagnostic(
            "orca-tunnel",
            "disconnected",
            exit_code=code,
            error_type=@async.with_timeout(1000, async fn() {
              classified.wait()
            }) catch {
              _ => "process_exit"
            },
            tunnel_directory=directory,
          )
          break
        }
        if (!connected || child is None) && @env.now() >= next_check {
          let alive = try {
            check_tunnel(state, directory)
            true
          } catch {
            _ => false
          }
          if !alive {
            if connected || child is None {
              break
            }
            @async.sleep(100)
            continue
          }
          next_check = @env.now() + 1000
        }
        if @env.now() >= next_probe || @fs.exists(directory + "/probe-request") {
          match relay_readiness(state, directory, git_enabled) {
            Ready => {
              failures = 0
              attempt = 0
              if !connected {
                connected = true
                git_relay_status(
                  directory,
                  if git_enabled {
                    "ready"
                  } else {
                    "disabled"
                  },
                )
                tunnel_status(directory, "connected")
              }
              if @fs.exists(directory + "/probe-request") {
                @fs.remove(directory + "/probe-request")
              }
              next_probe = @env.now() + 10000
            }
            Unsupported => {
              terminal = true
              tunnel_status(directory, "unsupported")
              break
            }
            Retry(reason) => {
              failures += 1
              connected = false
              git_relay_status(directory, "unavailable")
              tunnel_status(directory, "checking")
              save_diagnostic(
                "relay-recovery",
                "failed",
                attempt=failures,
                error_type=reason,
                tunnel_directory=directory,
              )
              if failures >= 2 {
                break
              }
              continue
            }
          }
        }
        @async.sleep(100)
      }
    }) catch {
      _ =>
        if @fs.exists(enabled) {
          save_diagnostic(
            "orca-tunnel",
            "process-error",
            tunnel_directory=directory,
          )
        }
    }
    stop_tunnel_master(state, directory, verify=true)
    if terminal {
      return
    }
    if @fs.exists(enabled) {
      tunnel_status(directory, "disconnected")
      attempt = if attempt < 6 { attempt + 1 } else { 6 }
      let delay = if attempt < 6 { 500 * (1 << attempt) } else { 30000 }
      save_diagnostic(
        "orca-tunnel",
        "retry",
        attempt~,
        retry_delay_ms=delay,
        tunnel_directory=directory,
      )
      for elapsed = 0
          elapsed < delay && @fs.exists(enabled)
          elapsed = elapsed + 100 {
        @async.sleep(100)
      }
    }
  }
  tunnel_status(directory, "stopped")
}

///|
async fn check_tunnel(state : Json, directory : String) -> Unit {
  @async.with_timeout(2000, async fn() {
    let (status, _, _) = @process.collect_output(
      "ssh",
      ssh_args(state) + ["-S", control_socket(state, directory), "-O", "check"],
    )
    guard status == 0 else { raise AdapterError("Tunnel not ready") }
    match field(state, "localPort") {
      Some(Json::Number(value, ..)) => {
        let socket = @socket.Tcp::connect(
          @socket.Addr::parse("127.0.0.1:" + value.to_int().to_string()),
        )
        socket.close()
      }
      None if field(state, "connection") == Some(Json::string("ssh")) => ()
      _ => raise AdapterError("Missing tunnel port")
    }
  })
}

///|
async fn worker_workspace(state : Json, directory : String) -> Json? {
  @async.with_timeout(10000, async fn() {
    @async.with_task_group(async fn(group) {
      let running = group.spawn(
        async fn() { workspace_running(state) },
        allow_failure=true,
        no_wait=true,
      )
      let query = group.spawn(async fn() {
        let current = workspace(state)
        if current is Some(value) &&
          field(value, "uid") == field(state, "workspaceUid") {
          set_field(value, "running", Json::boolean(running.wait()))
        }
        current
      })
      group.spawn_bg(no_wait=true, async fn() {
        while @fs.exists(directory + "/enabled") {
          @async.sleep(100)
        }
        query.cancel()
      })
      query.wait()
    })
  })
}
